package com.company.platform.analytics.api;
import com.company.platform.analytics.application.AnalyticsQueryService;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/analytics") public class AnalyticsController {private final AnalyticsQueryService query;public AnalyticsController(AnalyticsQueryService q){query=q;}@GetMapping("/overview") @PreAuthorize("hasAnyAuthority('ANALYTICS_READ','TENANT_OWNER','TENANT_ADMIN','TENANT_MANAGER')") public Map<String,Object> overview(@RequestParam(required=false)String from,@RequestParam(required=false)String to){return query.overview(from,to);}@GetMapping("/sales") @PreAuthorize("hasAnyAuthority('ANALYTICS_READ','TENANT_OWNER','TENANT_ADMIN','TENANT_MANAGER')") public List<Map<String,Object>> sales(@RequestParam(required=false)String from,@RequestParam(required=false)String to){return query.sales(from,to);}@GetMapping("/orders") @PreAuthorize("hasAnyAuthority('ANALYTICS_READ','TENANT_OWNER','TENANT_ADMIN','TENANT_MANAGER')") public List<Map<String,Object>> orders(@RequestParam(required=false)String from,@RequestParam(required=false)String to){return query.orders(from,to);}@GetMapping("/payments") @PreAuthorize("hasAnyAuthority('ANALYTICS_READ','TENANT_OWNER','TENANT_ADMIN','TENANT_MANAGER')") public List<Map<String,Object>> payments(@RequestParam(required=false)String from,@RequestParam(required=false)String to){return query.payments(from,to);}@GetMapping("/inventory") @PreAuthorize("hasAnyAuthority('ANALYTICS_READ','TENANT_OWNER','TENANT_ADMIN','TENANT_MANAGER')") public List<Map<String,Object>> inventory(@RequestParam(required=false)String from,@RequestParam(required=false)String to){return query.inventory(from,to);}@GetMapping("/products") @PreAuthorize("hasAnyAuthority('ANALYTICS_READ','TENANT_OWNER','TENANT_ADMIN','TENANT_MANAGER')") public List<Map<String,Object>> products(@RequestParam(required=false)String from,@RequestParam(required=false)String to){return query.products(from,to);}@ExceptionHandler(IllegalArgumentException.class) ResponseEntity<Map<String,String>> invalid(Exception e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}}
